const { resolve, join } = require('path')
const { existsSync } = require('fs')
const { platform } = require('./platform_info.js')

const loadPath = ['..', '..', 'bin']
if (platform != undefined) loadPath.push(platform)

if(!existsSync(join(__dirname, ...loadPath))) {
  loadPath.shift()
}

const targetName = (process.env.CONFIG == 'Debug') ?
                   'irissdk_d' :
                   'irissdk'

const irissdk = require(join(resolve(join(__dirname, ...loadPath)), targetName))
irissdk.registerBindingsPath(resolve(join(__dirname, ...loadPath)))

module.exports.irissdk = irissdk
